// Проверка HMAC-подписи (x-smm-signature) и обязательных полей
const crypto = require('crypto');
const raw = Buffer.isBuffer($input.first().binary?.data?.data)
  ? $input.first().binary.data.data.toString()
  : JSON.stringify($input.first().json.body ?? $input.first().json);
const headers = $input.first().json.headers ?? {};
const signature = headers['x-smm-signature'];
const secret = $env.N8N_WEBHOOK_TOKEN;

if (!secret) throw new Error('N8N_WEBHOOK_TOKEN is not configured');
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!signature || signature !== expected) {
  throw new Error('Invalid HMAC signature');
}

const body = typeof raw === 'string' ? JSON.parse(raw) : raw;
for (const field of ['workspace_id', 'job_type', 'idempotency_key']) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

return [{ json: body }];
